function [p] = gimbal_power(gd, power, rate_max)
%GIMBAL_POWER  The gimbal's power [W] at rate gd: power |gd|/rate_max.
%   gd: real[1] (passed a plain number)
%   power: real[1] (passed a plain number)
%   rate_max: real[1] (passed a plain number)
%   returns p: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    p = 0;
    p = ((power * asils.pc.fabs(gd)) / rate_max);
end
